export function createMicelialSfx(music){const seen=new Set();return{accept(events){for(const e of events){if(!e.type?.startsWith('micelial')||!e.id||seen.has(e.id))continue;if(seen.size>=96)seen.delete(seen.values().next().value);seen.add(e.id);const t=music.ctx?.currentTime||0,tone=(f,d,v=.04,delay=0,to=f)=>music.tone(f,d,'sine',v,t+delay,to,.006,true);if(e.type==='micelialPrepare'){tone(160,.15,.025,0,250);tone(240,.15,.02,.06,360);}else if(e.type==='micelialRelease'){tone(380,.14,.045,0,160);tone(520,.13,.025,.04,220);}else if(e.type==='micelialReverse'){tone(520,.09);tone(390,.11,.04,.08);}else if(e.type==='micelialBreak'){tone(720,.10,.06);tone(1080,.16,.04,.07);tone(1440,.2,.025,.13);}else if(e.type==='micelialHit')tone(240,.1,.025,0,170);else if(e.type==='micelialPhase'){tone(140,.24,.05,0,90);tone(480,.2,.025,.08,720);}}},reset(){seen.clear();}};}
